// Helper: get translation
const t=(lang:Lang,key:string,vars?:Record<string,any>)=>{
  let s=T[lang][key]||T["fr"][key]||key;
  if(vars)Object.keys(vars).forEach(k=>{s=s.replaceAll("{"+k+"}",String(vars[k]));});
  return s;
};

